cat >> ~/.config/mise/config.toml <<'EOF'

# Checkouts a fresh machine needs to be "skogai": config and infra only.
# No ref: apply clones missing ones and leaves existing checkouts alone;
# `mise bootstrap repos update` fast-forwards them.
[bootstrap.repos]
"~/.config/skogai" = { url = "https://github.com/skogai2/config.git" }
"~/.config/containers/systemd" = { url = "https://github.com/skogai/podman.git" }
"~/.skogai" = { url = "https://github.com/skogai2/dot-skogai.git" }
"/skogai" = { url = "https://github.com/skogai2/dash-skogai.git" }
EOF
mise bootstrap repos status; mise bootstrap repos apply --dry-run

cat >> ~/.config/mise/config.toml <<'EOF'

